// LEARN(ts.objects-classes.spread): spread copies one level; a nested update copies every level it changes.

interface Address {
  city: string;
  district: string;
}
interface Customer {
  readonly id: string;
  name: string;
  address: Address;
  tags: string[];
}

const customer = (): Customer => ({
  id: "c1",
  name: "Ayşe",
  address: { city: "İstanbul", district: "Kadıköy" },
  tags: ["vip"],
});

// Naive: the copy is new, but its address is the caller's address object.
function moveNaive(c: Customer, city: string): Customer {
  const copy = { ...c };
  copy.address.city = city;
  return copy;
}
const a = customer();
const b = moveNaive(a, "İzmir");
console.log(`naive: ${a.address.city} / ${b.address.city}`);

// Functional: copy each object on the path to the change, share the rest.
function move(c: Customer, city: string): Customer {
  return { ...c, address: { ...c.address, city } };
}
const c = customer();
const d = move(c, "Ankara");
console.log(`functional: ${c.address.city} / ${d.address.city}`);
console.log(`shared tags: ${d.tags === c.tags}, shared address: ${d.address === c.address}`);

// Later properties win, so defaults go first.
const defaults = { pageSize: 20, locale: "tr-TR" };
const fromUrl = { pageSize: 50 };
console.log({ ...defaults, ...fromUrl }, { ...fromUrl, ...defaults });

// Arrays: build new arrays instead of push, splice and sort.
const tags = ["vip", "yeni", "bayi"];
console.log([...tags, "kurumsal"], tags.filter((t) => t !== "yeni"));
console.log(tags.with(1, "eski"), tags.toSorted(), tags);

files.examples/02_rest_and_iterables.ts:
// LEARN(ts.objects-classes.spread): rest removes keys with a precise type; spread copies own data, not prototypes.

interface User {
  id: number;
  email: string;
  passwordHash: string;
}

// Rest collects the remaining properties, and its type drops the named ones.
function toPublic(user: User) {
  const { passwordHash, ...rest } = user;
  return rest; // { id: number; email: string }
}
const pub = toPublic({ id: 7, email: "ayse@example.com", passwordHash: "x1" });
console.log(pub);
// pub.passwordHash;
// error TS2339: Property 'passwordHash' does not exist on type '{ id: number; email: string; }'.

// Object spread copies own enumerable properties. Methods and getters live
// on the prototype, so a spread class instance is plain data.
class Price {
  amount: number;
  constructor(amount: number) {
    this.amount = amount;
  }
  get withVat(): number {
    return this.amount * 1.2;
  }
  format(): string {
    return `${this.amount} TL`;
  }
}
const copy = { ...new Price(100) };
console.log(Object.keys(copy), copy instanceof Price, "withVat" in copy);
// The spread type models this: no methods, no getters.
// copy.format();
// error TS2339: Property 'format' does not exist on type '{ amount: number; }'.

// Array spread takes any iterable: Set, Map entries, strings.
const tags = ["çay", "kahve", "çay"];
console.log([...new Set(tags)]);
const stock = new Map([["çay", 3]]);
const restocked = new Map([...stock, ["kahve", 5]]); // a new Map
console.log(stock.size, restocked.size);

// A string spreads into code points, while .length counts UTF-16 code units.
const word = "İz👍";
console.log(word.length, [...word].length);
const hex = (s: string) => [...s].map((ch) => ch.codePointAt(0)?.toString(16));
console.log(hex("İ".toLowerCase()), hex("İ".toLocaleLowerCase("tr")));

files.examples/03_deep_copy.ts:
// LEARN(ts.objects-classes.spread): structuredClone deep-copies data; JSON round trips lose types; neither copies behaviour.

const order = {
  id: "o-1",
  createdAt: new Date(Date.UTC(2026, 10, 13, 9, 30)),
  lines: [{ sku: "çay-500g", qty: 2 }],
  discounts: new Map([["kampanya", 10]]),
  note: undefined as string | undefined,
};

const shallow = { ...order }; // new top level, nested values shared
const viaJson = JSON.parse(JSON.stringify(order)); // deep, typed any
const deep = structuredClone(order); // deep, same type

for (const line of order.lines) line.qty = 99; // mutate the original
console.log(`qty: shallow ${shallow.lines[0]?.qty}, deep ${deep.lines[0]?.qty}`);

// JSON keeps only what JSON can say: Date -> string, Map -> {}, undefined -> gone.
console.log(typeof viaJson.createdAt, viaJson.discounts, "note" in viaJson);
// structuredClone keeps Date, Map, Set, typed arrays, undefined and even cycles.
console.log(deep.createdAt instanceof Date, deep.discounts.get("kampanya"), "note" in deep);

// viaJson is any, so this compiles and fails at run time:
try {
  viaJson.createdAt.getTime();
} catch (e) {
  console.log("JSON copy:", e instanceof TypeError ? "TypeError" : e);
}

// Classes: the clone is a plain object, but its static type is still Money.
class Money {
  amount: number;
  constructor(amount: number) {
    this.amount = amount;
  }
  format(): string {
    return `${this.amount.toFixed(2)} TL`;
  }
}
const cloned: Money = structuredClone(new Money(42));
console.log(cloned instanceof Money, cloned);
try {
  cloned.format(); // compiles: structuredClone<T>(value: T): T
} catch (e) {
  console.log("cloned.format():", e instanceof TypeError ? "TypeError" : e);
}

// Functions can't be cloned at all.
try {
  structuredClone({ onSave: () => "saved" });
} catch (e) {
  console.log(e instanceof DOMException ? e.name : e);
}
